class Transactions(BaseModel):
    transactions: list[Transaction]

last_month_transactions = query_ai_assistant(
    "Find all transactions from last month",
    output_schema=Transactions
)

for transaction in last_month_transactions.transactions:
    if transaction.subject.lower() == "bill":
        bill_transaction = query_ai_assistant(
            f"Find the transaction {transaction.id}",
            output_schema=Transaction
        )

send_money(
    recipient=bill_transaction.recipient,
    amount=bill_transaction.amount,
    subject=bill_transaction.subject,
    date="today"
)
